#!/usr/bin/env python3
"""Test host-to-host and internet reachability."""
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

NON_GUEST = {
    "B1-PC1": ("192.168.122.31", "10.1.1.10"),
    "B1-PC2": ("192.168.122.32", "10.1.1.11"),
    "B2-PC1": ("192.168.122.33", "10.1.2.10"),
    "B2-PC2": ("192.168.122.34", "10.1.2.11"),
    "B3-PC1": ("192.168.122.35", "10.1.3.10"),
    "B3-PC2": ("192.168.122.36", "10.1.3.11"),
    "B4-PC1": ("192.168.122.37", "10.2.1.10"),
    "B4-PC2": ("192.168.122.38", "10.2.1.11"),
}

GUEST = {
    "B4-PC3": ("192.168.122.39", "10.2.2.10"),
    "B4-PC4": ("192.168.122.40", "10.2.2.11"),
}

ALL_HOSTS = {**NON_GUEST, **GUEST}

def ping_from_host(src_name, src_mgmt, targets):
    """Ping all targets from a host. Returns dict of target_name: pass/fail."""
    results = {}
    try:
        conn = ConnectHandler(host=src_mgmt, device_type="linux", username="root", password="alpine")
        for tgt_name, tgt_ip in targets:
            try:
                out = conn.send_command(f"ping -c 2 -W 3 {tgt_ip}", read_timeout=15)
                results[tgt_name] = "0% packet loss" in out or "0 packet loss" in out or ", 0%" in out
            except Exception as e:
                results[tgt_name] = False
        conn.disconnect()
    except Exception as e:
        for tgt_name, _ in targets:
            results[tgt_name] = False
    return src_name, results

# Build test plan
tests = []
for src_name, (src_mgmt, src_ip) in ALL_HOSTS.items():
    targets = []
    # Ping other hosts (lab IPs)
    for tgt_name, (_, tgt_ip) in ALL_HOSTS.items():
        if src_name != tgt_name:
            targets.append((tgt_name, tgt_ip))
    # Ping internet
    targets.append(("8.8.8.8", "8.8.8.8"))
    targets.append(("1.1.1.1", "1.1.1.1"))
    tests.append((src_name, src_mgmt, targets))

all_results = {}
with ThreadPoolExecutor(max_workers=10) as pool:
    futures = [pool.submit(ping_from_host, name, mgmt, tgts) for name, mgmt, tgts in tests]
    for f in as_completed(futures):
        name, res = f.result()
        all_results[name] = res

# Print results
print("\n=== NON-GUEST TO NON-GUEST (should all pass) ===")
ng_pass = 0
ng_fail = 0
ng_failures = []
for src in sorted(NON_GUEST.keys()):
    for dst in sorted(NON_GUEST.keys()):
        if src == dst:
            continue
        ok = all_results[src].get(dst, False)
        if ok:
            ng_pass += 1
        else:
            ng_fail += 1
            ng_failures.append(f"  {src} -> {dst}")
print(f"  Pass: {ng_pass}, Fail: {ng_fail}")
if ng_failures:
    print("  Failures:")
    for f in ng_failures:
        print(f)

print("\n=== GUEST TO GUEST (should pass) ===")
for src in sorted(GUEST.keys()):
    for dst in sorted(GUEST.keys()):
        if src == dst:
            continue
        ok = all_results[src].get(dst, False)
        print(f"  {src} -> {dst}: {'PASS' if ok else 'FAIL'}")

print("\n=== GUEST <-> NON-GUEST (should all fail) ===")
cross_expected_fail = 0
cross_unexpected_pass = 0
cross_unexpected_details = []
for src in sorted(GUEST.keys()):
    for dst in sorted(NON_GUEST.keys()):
        ok = all_results[src].get(dst, False)
        if ok:
            cross_unexpected_pass += 1
            cross_unexpected_details.append(f"  {src} -> {dst}: UNEXPECTED PASS")
        else:
            cross_expected_fail += 1
for src in sorted(NON_GUEST.keys()):
    for dst in sorted(GUEST.keys()):
        ok = all_results[src].get(dst, False)
        if ok:
            cross_unexpected_pass += 1
            cross_unexpected_details.append(f"  {src} -> {dst}: UNEXPECTED PASS")
        else:
            cross_expected_fail += 1
print(f"  Expected failures: {cross_expected_fail}, Unexpected passes: {cross_unexpected_pass}")
if cross_unexpected_details:
    for d in cross_unexpected_details:
        print(d)

print("\n=== INTERNET REACHABILITY (should all pass) ===")
inet_pass = 0
inet_fail = 0
inet_failures = []
for src in sorted(ALL_HOSTS.keys()):
    for tgt in ["8.8.8.8", "1.1.1.1"]:
        ok = all_results[src].get(tgt, False)
        if ok:
            inet_pass += 1
        else:
            inet_fail += 1
            inet_failures.append(f"  {src} -> {tgt}")
print(f"  Pass: {inet_pass}, Fail: {inet_fail}")
if inet_failures:
    print("  Failures:")
    for f in inet_failures:
        print(f)
